 midSideAttachment=std::make_unique<ButtonAttachment>(processor.parameters,model::id(selected,"K_MS"),midSide);oversampleAttachment=std::make_unique<ButtonAttachment>(processor.parameters,model::id(selected,"K_OS"),oversample);spectralFreezeAttachment=std::make_unique<ButtonAttachment>(processor.parameters,model::id(selected,"S_FREEZE"),spectralFreeze);windowAttachment=std::make_unique<ComboAttachment>(processor.parameters,model::id(selected,"S_WINDOW"),spectreWindow);
