void MonoJuiceAudioProcessorEditor::refreshPreset(){const int index=processor.matchingFactoryPreset(selected);presetMenu.setSelectedId(index+1,juce::dontSendNotification);presetMenu.setTooltip(juce::String(factory::description(type,index))+". Load affects only this bank, keeps ON and clears its history. Stop transport for window changes. CUSTOM means parameters differ from factory.");}
void MonoJuiceAudioProcessorEditor::showSlot(int i){selected=juce::jlimit(0,4,i);processor.selectedSlot.store(selected);const auto current=processor.settings().slots[selected];type=current.type;variant=type==4?current.colour.model:(current.spectralExtended?1:0);bindControls();for(int s=0;s<5;s++)tabs[s].setToggleState(s==selected,juce::dontSendNotification);showPage(0);}
void MonoJuiceAudioProcessorEditor::showPage(int value){const int last=lastPage(type,variant);page=juce::jlimit(0,last,value);for(auto& slider:sliders)slider.setVisible(false);
 auto show=[&](int i){sliders[size_t(i)].setVisible(true);};
 auto lfo=[&]{for(int i=130;i<134;i++)show(i);};
 if(type==1){if(page==0)for(int i=0;i<4;i++)show(i);if(page==1){for(int i=65;i<69;i++)show(i);lfo();}}
 else if(type==2){if(page==0)for(int i=4;i<12;i++)show(i);if(page==1){for(int i=69;i<77;i++)show(i);lfo();}}
 else if(type==3){if(page==0)for(int i=12;i<24;i++)show(i);if(page==1)for(int i=77;i<89;i++)show(i);if(page==2)lfo();}
 else if(type==4){if(variant){if(page==0)for(int i=24;i<36;i++)show(i);if(page==1)for(int i=36;i<42;i++)show(i);if(page==2)for(int i=58;i<65;i++)show(i);if(page==3)for(int i=89;i<101;i++)show(i);if(page==4){for(int i=101;i<107;i++)show(i);for(int i=123;i<129;i++)show(i);}if(page==5){show(129);lfo();}}else{if(page==0)for(int i=52;i<61;i++)show(i);if(page==1)for(int i=61;i<65;i++)show(i);if(page==2){for(int i=117;i<123;i++)show(i);for(int i=123;i<129;i++)show(i);}if(page==3){show(129);lfo();}}}
 else if(type==5){if(variant){if(page==0)for(int i=42;i<52;i++)show(i);if(page==1)for(int i=107;i<117;i++)show(i);if(page==2)lfo();}else{if(page==0)for(int i=42;i<44;i++)show(i);if(page==1){show(107);show(108);lfo();}}}
 if(type==2)sliders[7].setTooltip("Chorus / Mix. V2: 0 = clean input at any INP, 127 = full effect, smoothed outside the DSP core. V1: original internal mix, pre-fix sound.");
 const int route=processor.settings().slots[selected].odin.routing;sliders[54].setEnabled(route!=0);sliders[55].setEnabled(route!=0);sliders[56].setEnabled(route==2);
 freeze.setVisible(type==3);metalPreset.setVisible(type==3);midSide.setVisible(type==4&&variant);oversample.setVisible(type==4&&variant);panic.setVisible(type==4);negativeA.setVisible(type==4&&!variant);negativeB.setVisible(type==4&&!variant);odinRouting.setVisible(type==4&&!variant);modelMenu.setVisible(type==4||type==5);
 spectreWindow.setVisible(type==5);spectralFreeze.setVisible(type==5&&variant);chorusMode.setVisible(type==2);previousPage.setVisible(last>0);nextPage.setVisible(last>0);previousPage.setEnabled(page>0);nextPage.setEnabled(page<last);init.setEnabled(type!=0);clear.setEnabled(type!=0);randomise.setEnabled(type!=0);presetMenu.setVisible(type==4||type==5);refreshPreset();moveLeft.setEnabled(selected>0);moveRight.setEnabled(selected<4);resized();repaint();}
